CREATE OR REPLACE FUNCTION private.mfa_impl_pickup_report_create(p_order_ids uuid[], p_request_id uuid, p_allow_duplicates boolean DEFAULT false, p_package_counts jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_owner uuid:=private.pickup_report_owner(); v_data jsonb; v_items jsonb; v_sender jsonb; v_report jsonb;
 v_id uuid:=gen_random_uuid(); v_created timestamptz:=now(); v_year integer:=extract(year FROM now() AT TIME ZONE 'Europe/Madrid');
 v_seq integer; v_number text; v_fingerprint jsonb; v_existing public.pickup_reports%rowtype; v_entry record;
BEGIN
 IF p_request_id IS NULL THEN RAISE EXCEPTION 'PICKUP_REQUEST_ID_REQUIRED' USING ERRCODE='22023'; END IF;
 IF cardinality(p_order_ids)<>(SELECT count(DISTINCT x) FROM unnest(p_order_ids) x)
 THEN RAISE EXCEPTION 'PICKUP_DUPLICATE_SELECTION' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p_package_counts) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'PICKUP_INVALID_PACKAGES' USING ERRCODE='22023'; END IF;
 FOR v_entry IN SELECT * FROM jsonb_each(p_package_counts) LOOP
 IF jsonb_typeof(v_entry.value)<>'number' OR v_entry.value::text !~ '^([1-9]|[1-9][0-9]|100)$'
 OR NOT(v_entry.key=ANY(SELECT x::text FROM unnest(p_order_ids) x))
 THEN RAISE EXCEPTION 'PICKUP_INVALID_PACKAGES' USING ERRCODE='22023'; END IF;
 END LOOP;
 v_fingerprint:=jsonb_build_object('ids',(SELECT jsonb_agg(x ORDER BY x) FROM (SELECT DISTINCT unnest(p_order_ids) x)s),
 'packages',p_package_counts,'allowDuplicates',coalesce(p_allow_duplicates,false));
 -- One transaction per tenant serializes counter, retry and overlapping membership
 -- decisions. Hash collisions merely serialize unrelated tenants, never authorize.
 PERFORM pg_advisory_xact_lock(hashtextextended('pickup-report:'||v_owner::text,0));
 SELECT * INTO v_existing FROM public.pickup_reports WHERE owner_id=v_owner AND request_id=p_request_id;
 IF FOUND THEN
 IF v_existing.request_fingerprint<>v_fingerprint THEN RAISE EXCEPTION 'PICKUP_REQUEST_REUSED' USING ERRCODE='22023'; END IF;
 RETURN v_existing.snapshot;
 END IF;
 -- Snapshot labels may live on canonical siblings, so lock every existing
 -- sibling in the same stable order used by all receipt transactions.
 PERFORM o.id FROM public.fulfillment_orders o WHERE o.owner_id=v_owner AND (o.id=ANY(p_order_ids) OR EXISTS(
 SELECT 1 FROM public.fulfillment_orders requested WHERE requested.owner_id=v_owner AND requested.id=ANY(p_order_ids)
 AND requested.source_channel IN ('amazon','shopify') AND nullif(trim(requested.order_number),'') IS NOT NULL
 AND o.source_channel=requested.source_channel AND o.source_integration_account_id IS NOT DISTINCT FROM requested.source_integration_account_id
 AND trim(o.order_number)=trim(requested.order_number)))
 ORDER BY o.id FOR UPDATE OF o;
 v_data:=private.pickup_report_preview_items(v_owner,p_order_ids);
 IF NOT (v_data->>'canCreate')::boolean THEN RAISE EXCEPTION 'PICKUP_INELIGIBLE_ORDERS' USING ERRCODE='22023'; END IF;
 IF NOT coalesce(p_allow_duplicates,false) AND EXISTS(SELECT 1 FROM jsonb_array_elements(v_data->'items') item WHERE jsonb_array_length(item->'previousReports')>0)
 THEN RAISE EXCEPTION 'PICKUP_ALREADY_REPORTED' USING ERRCODE='22023'; END IF;
 SELECT jsonb_build_object('legalName',legal_name,'taxId',tax_id,
 'address',concat_ws(', ',nullif(address_line1,''),nullif(address_line2,''),nullif(concat_ws(' ',postal_code,city),''),nullif(province,''),nullif(country_code,'')),
 'email',email,'phone',phone) INTO v_sender FROM public.business_settings WHERE owner_id=v_owner;
 IF v_sender IS NULL OR nullif(trim(v_sender->>'legalName'),'') IS NULL THEN RAISE EXCEPTION 'PICKUP_SENDER_REQUIRED' USING ERRCODE='22023'; END IF;
 SELECT jsonb_agg((item-'orderKey'-'previousReports'-'issue'-'eligible')||jsonb_build_object(
 'packages',coalesce((p_package_counts->>(item->>'orderId'))::integer,1),
 'packageCountEstimated',NOT(p_package_counts ? (item->>'orderId')))) INTO v_items FROM jsonb_array_elements(v_data->'items') item;
 INSERT INTO private.pickup_report_counters(owner_id,report_year,last_number) VALUES(v_owner,v_year,1)
 ON CONFLICT(owner_id,report_year) DO UPDATE SET last_number=private.pickup_report_counters.last_number+1 RETURNING last_number INTO v_seq;
 v_number:='REC-'||v_year::text||'-'||lpad(v_seq::text,greatest(4,length(v_seq::text)),'0');
 v_report:=jsonb_build_object('id',v_id,'number',v_number,'createdAt',v_created,'createdBy',auth.uid(),
 'sender',v_sender,'items',v_items,'totalPackages',(SELECT sum((item->>'packages')::integer) FROM jsonb_array_elements(v_items) item));
 INSERT INTO public.pickup_reports(id,owner_id,request_id,request_fingerprint,number,created_at,created_by,snapshot)
 VALUES(v_id,v_owner,p_request_id,v_fingerprint,v_number,v_created,auth.uid(),v_report);
 INSERT INTO public.pickup_report_items(report_id,owner_id,order_id,order_key)
 SELECT v_id,v_owner,(item->>'orderId')::uuid,item->>'orderKey' FROM jsonb_array_elements(v_data->'items') item;
 RETURN v_report;
END $function$

CREATE OR REPLACE FUNCTION private.orders_dashboard_projection_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '25ms'
AS $function$
DECLARE old_key text;new_key text;
BEGIN
 BEGIN
  IF NOT coalesce((SELECT maintenance_enabled FROM private.orders_projection_control WHERE singleton),false) THEN RETURN NULL;END IF;
  IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NULL;END IF;
  IF TG_OP<>'INSERT' THEN
   old_key:=private.orders_dashboard_group_key(OLD.source_channel,OLD.order_number,OLD.id);
   INSERT INTO private.orders_projection_dirty(owner_id,group_key)
   VALUES(OLD.owner_id,old_key);
  END IF;
  IF TG_OP<>'DELETE' THEN
   new_key:=private.orders_dashboard_group_key(NEW.source_channel,NEW.order_number,NEW.id);
   IF TG_OP='INSERT' OR NEW.owner_id IS DISTINCT FROM OLD.owner_id OR new_key IS DISTINCT FROM old_key THEN
    INSERT INTO private.orders_projection_dirty(owner_id,group_key) VALUES(NEW.owner_id,new_key);
   END IF;
  END IF;
 EXCEPTION WHEN OTHERS THEN
  BEGIN
   PERFORM private.orders_projection_record_failure(SQLSTATE,
    CASE WHEN TG_OP='DELETE' THEN OLD.owner_id ELSE NEW.owner_id END,
    CASE WHEN TG_OP='DELETE' THEN private.orders_dashboard_group_key(OLD.source_channel,OLD.order_number,OLD.id)
    ELSE private.orders_dashboard_group_key(NEW.source_channel,NEW.order_number,NEW.id) END);
  EXCEPTION WHEN OTHERS THEN RAISE LOG 'orders projection queue and recorder unavailable';
  END;
 END;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION private.orders_dashboard_projection_tracking_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '25ms'
AS $function$
  DECLARE old_id uuid;new_id uuid;
  BEGIN
   BEGIN
    IF NOT coalesce((SELECT maintenance_enabled FROM private.orders_projection_control WHERE singleton),false) THEN RETURN NULL;END IF;
    IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NULL;END IF;
    IF TG_OP<>'INSERT' THEN old_id:=OLD.order_id;END IF;
    IF TG_OP<>'DELETE' THEN new_id:=NEW.order_id;END IF;
    INSERT INTO private.orders_projection_dirty(owner_id,group_key)
    SELECT f.owner_id,private.orders_dashboard_group_key(f.source_channel,f.order_number,f.id)
    FROM public.fulfillment_orders f WHERE f.id IN(old_id,new_id);
   EXCEPTION WHEN OTHERS THEN
    BEGIN PERFORM private.orders_projection_record_failure(SQLSTATE);
    EXCEPTION WHEN OTHERS THEN RAISE LOG 'orders tracking projection queue and recorder unavailable';END;
   END;
   RETURN NULL;
  END $function$

CREATE OR REPLACE FUNCTION private.pickup_report_owner()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_owner uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='42501'; END IF;
 PERFORM public.security_mfa_assert(false);
 v_owner:=private.app_workspace_owner_id();
 IF v_owner IS NULL THEN RAISE EXCEPTION 'ACCESS_DISABLED' USING ERRCODE='42501'; END IF;
 IF NOT coalesce(private.app_has_permission('orders'),false) THEN
 RAISE EXCEPTION 'PICKUP_ORDERS_PERMISSION_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN v_owner;
END $function$

CREATE OR REPLACE FUNCTION public.pickup_document_complete(p_owner uuid, p_actor uuid, p_report uuid, p_request uuid, p_lease uuid, p_artifact jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.pickup_document_state%rowtype;o private.pickup_document_operations%rowtype;v_groups integer;v_count integer;v_complete boolean;v_root text;v_report jsonb;begin
 perform private.pickup_document_assert(p_owner,p_actor);perform pg_advisory_xact_lock(hashtextextended('pickup-document:'||p_report::text,0));
 select * into o from private.pickup_document_operations where owner_id=p_owner and request_id=p_request and report_id=p_report and actor_id=p_actor for update;
 if not found then raise exception 'PICKUP_OPERATION_NOT_FOUND';end if;if o.status='completed' then return private.pickup_document_json(p_report);end if;
 select * into s from private.pickup_document_state where report_id=p_report and owner_id=p_owner for update;
 v_report:=private.pickup_report_effective(p_report);
 if jsonb_typeof(o.input->'verifiedOrderIds') is distinct from 'array' or jsonb_array_length(o.input->'verifiedOrderIds')=0 or jsonb_array_length(o.input->'verifiedOrderIds')>2000 then raise exception 'PICKUP_VERIFICATION_REQUIRED';end if;
 if coalesce(o.input->>'reportRevision','') !~ '^[0-9]{1,9}$' or (o.input->>'reportRevision')::integer<>s.revision then raise exception 'PICKUP_VERIFICATION_STALE';end if;
 if (select coalesce(jsonb_agg(id order by id),'[]'::jsonb) from jsonb_array_elements_text(o.input->'verifiedOrderIds') id) is distinct from
 (select coalesce(jsonb_agg(i->>'orderId' order by i->>'orderId'),'[]'::jsonb) from jsonb_array_elements(v_report->'items') i where trim(i->>'carrier')=o.carrier) then raise exception 'PICKUP_VERIFICATION_STALE';end if;
 if (o.input->>'packages')::integer is distinct from (select sum((i->>'packages')::integer) from jsonb_array_elements(v_report->'items')i where trim(i->>'carrier')=o.carrier) then raise exception 'PICKUP_INVALID_PACKAGES';end if;

 if s.lease is distinct from p_lease or s.lease_request is distinct from p_request or s.lease_until<=now() or s.status in ('signed','void') or s.pii_purged_at is not null or s.expires_at<=now() then raise exception 'PICKUP_LEASE_LOST';end if;
 v_root:=p_owner::text||'/'||p_report::text||'/'||p_request::text;
 if coalesce(p_artifact->>'pdfHash','') !~ '^[a-f0-9]{64}$' or (s.stamp_path is null and p_artifact->>'stampPath' is distinct from v_root||'/stamp.png') or (s.stamp_path is not null and p_artifact->>'stampPath' is distinct from s.stamp_path)
 or (p_artifact->>'logoPath' is not null and p_artifact->>'logoPath' not in (v_root||'/logo.png',coalesce(s.logo_path,''))) then raise exception 'PICKUP_INVALID_ARTIFACT';end if;
 insert into private.pickup_document_signatures(report_id,owner_id,carrier,request_id,driver_name,identifier,received_at,packages,signature_path,signature_hash,created_by)
 values(p_report,p_owner,o.carrier,p_request,trim(o.input->>'driverName'),trim(o.input->>'identifier'),(o.input->>'receivedAt')::timestamptz,(o.input->>'packages')::integer,o.signature_path,o.input->>'signatureHash',p_actor);
 select count(distinct trim(i->>'carrier')) into v_groups from public.pickup_reports r,jsonb_array_elements(private.pickup_report_effective(r.id)->'items')i where r.id=p_report;
 select count(*) into v_count from private.pickup_document_signatures where report_id=p_report;v_complete:=v_count=v_groups;
 update private.pickup_document_state set status=case when v_complete then 'signed' else 'partial' end,revision=revision+1,pdf_path=o.pdf_path,pdf_hash=p_artifact->>'pdfHash',stamp_path=coalesce(stamp_path,p_artifact->>'stampPath'),logo_path=coalesce(logo_path,p_artifact->>'logoPath'),
 first_signed_at=coalesce(first_signed_at,now()),expires_at=coalesce(expires_at,now()+make_interval(days=>coalesce((select retention_days from private.pickup_document_config where id),365))),signed_at=case when v_complete then now() end,signed_by=case when v_complete then p_actor end,
 lease=null,lease_request=null,lease_until=null where report_id=p_report;
 update private.pickup_document_operations set status='completed',completed_at=now(),input='{}' where owner_id=p_owner and request_id=p_request;
 insert into public.audit_logs(workspace_owner_id,actor_user_id,module,action,entity_type,entity_id,entity_label,summary,details)
 select p_owner,p_actor,'orders','sign_pickup_report','pickup_report',p_report::text,r.number,'Firma registrada en informe de recogida',jsonb_build_object('carrier',o.carrier,'packages',(o.input->>'packages')::integer,'signatureHash',o.input->>'signatureHash','pdfHash',p_artifact->>'pdfHash') from public.pickup_reports r where r.id=p_report;
 return private.pickup_document_json(p_report);
end$function$
